/**
 * Israel city seed dataset (PR-LOCATION-CITIES-1).
 *
 * 1272 cities/towns/villages, normalized from the GabMic
 * Israeli-cities Gist (snapshot 2019-07). Each row carries the
 * official Israeli CBS city_symbol, the Hebrew name, the
 * English name, and pre-computed lower-case search-only
 * normalizations.
 *
 * Hard rules (CEO directive 2026-05-10):
 *   - Pure data + helpers. NO runtime fetch from any Gist or
 *     external host. NO network call.
 *   - Postcodes intentionally empty (source has none; we DO NOT
 *     invent postcodes). A future PR may layer postcode data
 *     once the CEO has approved a postcode source.
 *   - district / region intentionally null (source has none).
 *   - aliases intentionally empty (no manufactured aliases).
 *   - isActive defaults to true; data review is required before
 *     production booking matching uses any individual row.
 *   - priority is a small popular-cities rank (100 for the top
 *     ~20 cities by Israeli population, 0 for the rest). It is
 *     a UI ranking signal only — never a security or pricing
 *     signal.
 *   - normalizedHebrew / normalizedEnglish are search-only and
 *     never displayed.
 *
 * Known source quirks preserved as-imported (documented in
 * docs/location/israel-cities-dataset.md):
 *   - The source has BiDi-flipped parens ")...(" inside some
 *     Hebrew names (tribal / variant tags). The normalizer
 *     strips them out for search, but the displayed Hebrew name
 *     keeps the source character order — BiDi-aware UI renders
 *     them correctly.
 *   - 6 rows have no English name in the source. We preserve
 *     them with englishName === '' so callers can opt-in to a
 *     transliteration backfill later.
 *   - Some English names are truncated to 21 chars in the source
 *     (e.g. "MODI'IN-MAKKABBIM-RE"). Documented in the dataset
 *     doc; corrected names go into aliases in a future PR.
 *
 * Source seed (one-time only; not a runtime dependency):
 *   https://gist.github.com/GabMic/57cc6b03eefcb47e731003c109e3a67a
 */

export interface IsraelCity {
  /** Official Israeli CBS city symbol (string, leading zeros preserved). */
  citySymbol: string;
  /** Hebrew city name as stored in the source (whitespace trimmed). */
  hebrewName: string;
  /** English city name as stored in the source (whitespace trimmed). May be empty. */
  englishName: string;
  /** Hebrew name with parens / punctuation stripped, whitespace collapsed. Search-only. */
  normalizedHebrew: string;
  /** English name lower-cased, punctuation stripped. Search-only. */
  normalizedEnglish: string;
  /** Approved alias names. Empty in Phase 1; future PRs may add manually-curated aliases. */
  aliases: readonly string[];
  /** Israeli administrative district. null until a future PR layers district data. */
  district: string | null;
  /** Israeli administrative region (sub-district). null until a future PR layers region data. */
  region: string | null;
  /** Postcodes for this city. Empty in Phase 1 — source has none and we do NOT invent. */
  postcodes: readonly string[];
  /** Whether this city is eligible for booking matching. true by default; review before relying on it. */
  isActive: boolean;
  /** UI ranking signal: 100 for the ~20 most populous cities, 0 otherwise. UI use only. */
  priority: number;
  /** Provenance tag — fixed string for the Phase-1 seed. */
  source: "gabmic-israel-cities-seed";
  /** Free-form note. null unless a city carries a known caveat. */
  notes: string | null;
}

export const ISRAEL_CITIES_SOURCE = "gabmic-israel-cities-seed" as const;
export const ISRAEL_CITIES_SOURCE_VERSION = "2019-07" as const;

