// ─────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────

/** Return the full city array. Stable reference; do NOT mutate. */
export function getIsraelCities(): readonly IsraelCity[] {
  return ISRAEL_CITIES;
}

/** Return the city with the given CBS city symbol, or undefined. */
export function findIsraelCityBySymbol(symbol: string): IsraelCity | undefined {
  if (!symbol) return undefined;
  const trimmed = symbol.trim();
  if (!trimmed) return undefined;
  return ISRAEL_CITIES.find((c) => c.citySymbol === trimmed);
}

/** Return the popular-city subset, sorted by priority desc then English name. */
export function getPopularIsraelCities(): readonly IsraelCity[] {
  return ISRAEL_CITIES
    .filter((c) => c.priority > 0 && c.isActive)
    .slice()
    .sort((a, b) => b.priority - a.priority || a.normalizedEnglish.localeCompare(b.normalizedEnglish));
}

const HE_NON_LETTER_RE = /[^\u0590-\u05FF\s]+/g;
const EN_NON_ALNUM_RE = /[^a-z0-9\s]+/g;
const WS_RUN_RE = /\s+/g;

/** Strip punctuation, collapse whitespace, lower-case-equivalent (Hebrew has no case). Search-only. */
export function normalizeHebrewCitySearch(value: string): string {
  if (!value) return '';
  const stripped = value.replace(HE_NON_LETTER_RE, ' ');
  return stripped.replace(WS_RUN_RE, ' ').trim();
}

/** Lower-case, strip non-alphanumeric, collapse whitespace. Search-only. */
export function normalizeEnglishCitySearch(value: string): string {
  if (!value) return '';
  const lower = value.toLowerCase();
  const stripped = lower.replace(EN_NON_ALNUM_RE, ' ');
  return stripped.replace(WS_RUN_RE, ' ').trim();
}

/** Locale-aware case-insensitive substring search.
 *  - locale='he' searches normalizedHebrew
 *  - locale='en' searches normalizedEnglish
 *  Returns up to `limit` results (default 25), priority cities first. */
export function searchIsraelCities(
  query: string,
  locale: 'he' | 'en' = 'en',
  limit: number = 25,
): readonly IsraelCity[] {
  if (!query) return [];
  const needle =
    locale === 'he'
      ? normalizeHebrewCitySearch(query)
      : normalizeEnglishCitySearch(query);
  if (!needle) return [];
  const matches = ISRAEL_CITIES.filter((c) => {
    const haystack = locale === 'he' ? c.normalizedHebrew : c.normalizedEnglish;
    return haystack.includes(needle);
  });
  matches.sort((a, b) => b.priority - a.priority || a.normalizedEnglish.localeCompare(b.normalizedEnglish));
  return matches.slice(0, Math.max(0, limit));
}
